{
  "experiment": "exp54_causal_probe_subspace",
  "description": "Causal probe: does classification DAPT compress discriminative info into top SVD components?",
  "server": "westd-49690",
  "layer": 10,
  "models": ["9-class (plan_002)", "scrambled (plan_003)", "MLM-only (plan_017)"],
  "note": "MLM-only used as vanilla baseline (server has no internet for HF download). Stronger control: isolates classification DAPT effect from fine-tuning.",
  "evaluation": "OOD jailbreak mixed with IID test benign (38 samples) for balanced binary classification",
  "top_k_svd_probe_f1": {
    "9-class": {
      "top_3":  {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 1.000, "fitd_ood": 1.000},
      "top_5":  {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 1.000, "fitd_ood": 1.000},
      "top_9":  {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 1.000, "fitd_ood": 1.000},
      "top_20": {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 1.000, "fitd_ood": 1.000},
      "top_50": {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 1.000, "fitd_ood": 1.000},
      "full_768": {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 1.000, "fitd_ood": 1.000}
    },
    "scrambled": {
      "top_3":  {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 0.962, "fitd_ood": 1.000},
      "top_5":  {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 0.962, "fitd_ood": 1.000},
      "full_768": {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 0.962, "fitd_ood": 1.000}
    },
    "MLM-only": {
      "top_3":  {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 0.618, "fitd_ood": 1.000},
      "top_5":  {"iid_test": 1.000, "dd_ood": 0.990, "aa_ood": 0.644, "fitd_ood": 1.000},
      "full_768": {"iid_test": 1.000, "dd_ood": 1.000, "aa_ood": 0.636, "fitd_ood": 1.000}
    }
  },
  "random_projection_f1_k5": {
    "9-class":   {"dd_ood": 0.994, "aa_ood": 0.952, "fitd_ood": 1.000},
    "scrambled":  {"dd_ood": 0.973, "aa_ood": 0.807, "fitd_ood": 1.000},
    "MLM-only":   {"dd_ood": 0.685, "aa_ood": 0.584, "fitd_ood": 0.744}
  },
  "key_findings": [
    "9-class model: perfect F1=1.000 on all OOD sets with just 3 SVD dimensions (out of 768). Discriminative info fully concentrated in compressed subspace.",
    "MLM-only model: AA-OOD F1=0.636 even with full 768 dims. No discriminative structure from classification DAPT = no OOD generalization on hardest set.",
    "Random projections systematically worse: 9-class random k=3 AA-OOD=0.928 vs top-3=1.000; MLM-only random k=5 DD=0.685, AA=0.584, FITD=0.744.",
    "Scrambled model intermediate: AA-OOD=0.962 (some compression from partially-aligned labels), but random k=3 AA=0.766 (less stable).",
    "DD-OOD and FITD-OOD are easily separable for all models (F1~1.0). ActorAttack (AA-OOD) is the discriminative test case.",
    "Hypothesis CONFIRMED: classification DAPT creates a low-dimensional discriminative subspace that causally enables OOD jailbreak detection."
  ]
}

